private void removeDeferDirective(TraverserContext<?> context) {
  try {
    Object dummyRoot = null;
    TraverserContext<?> curr = context;
    while (curr != null) {
      Object node = curr.thisNode();
      if (node != null && node.getClass().getName().contains("DummyRoot")) {
        dummyRoot = node;
        break;
      }
      if (curr.getParentNode() != null && curr.getParentNode().getClass().getName().contains("DummyRoot")) {
        dummyRoot = curr.getParentNode();
        break;
      }
      curr = curr.getParentContext();
    }
    if (dummyRoot != null) {
      // 1. Modify schema field in DummyRoot
      java.lang.reflect.Field schemaField = dummyRoot.getClass().getDeclaredField("schema");
      schemaField.setAccessible(true);
      graphql.schema.GraphQLSchema schema = (graphql.schema.GraphQLSchema) schemaField.get(dummyRoot);
      if (schema != null) {
        cleanSchemaDirectives(schema);
      }

      // 2. Modify directives field in DummyRoot
      java.lang.reflect.Field directivesField = dummyRoot.getClass().getDeclaredField("directives");
      directivesField.setAccessible(true);
      java.util.Set<?> directives = (java.util.Set<?>) directivesField.get(dummyRoot);
      if (directives != null) {
        java.util.Set<Object> filteredDirectives = new java.util.HashSet<>();
        for (Object d : directives) {
          if (d instanceof graphql.schema.GraphQLDirective) {
            String name = ((graphql.schema.GraphQLDirective) d).getName();
            if (!"defer".equals(name) && !"experimental_disableErrorPropagation".equals(name)) {
              filteredDirectives.add(d);
            }
          }
        }
        directivesField.set(dummyRoot, filteredDirectives);
      }
    }
  } catch (Throwable t) {
    // Ignore
  }
}

private void cleanSchemaDirectives(graphql.schema.GraphQLSchema schema) {
  try {
    java.util.List<graphql.schema.GraphQLDirective> filteredDirectives = new java.util.ArrayList<>();
    for (graphql.schema.GraphQLDirective d : schema.getDirectives()) {
      if (!"defer".equals(d.getName()) && !"experimental_disableErrorPropagation".equals(d.getName())) {
        filteredDirectives.add(d);
      }
    }

    java.util.List<graphql.schema.GraphQLAppliedDirective> filteredApplied = schema.getSchemaAppliedDirectives();
    Class<?> holderClass = Class.forName("graphql.DirectivesUtil$DirectivesHolder");
    java.lang.reflect.Constructor<?> holderConstructor = holderClass.getConstructor(java.util.Collection.class, java.util.Collection.class);
    Object newHolder = holderConstructor.newInstance(filteredDirectives, filteredApplied);

    java.lang.reflect.Field holderField = graphql.schema.GraphQLSchema.class.getDeclaredField("directiveDefinitionsHolder");
    holderField.setAccessible(true);
    holderField.set(schema, newHolder);
  } catch (Throwable t) {
    // Ignore
  }
}

